const MONTHS = ["janv.","févr.","mars","avr.","mai","juin","juil.","août","sept.","oct.","nov.","déc."];
const MONTHS_FULL = ["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
function fmtDate(iso){ const d=new Date(iso+"T00:00:00"); return {d:d.getDate(), m:MONTHS[d.getMonth()], full:d.getDate()+" "+MONTHS_FULL[d.getMonth()]+" "+d.getFullYear()}; }
function fmtPrice(n){ return n.toLocaleString('fr-FR')+" FCFA"; }

/* ============ TOAST / MODAL ============ */
function toast(msg){
  const t=document.getElementById('toast');
  t.innerHTML=`${ic('star',18)}${msg}`;
  t.querySelector('span').style.color = "#8FE0B6";
  t.classList.add('show');
  clearTimeout(window._toastTimer);
  window._toastTimer=setTimeout(()=>t.classList.remove('show'),3200);
}
function openModal(html){
  document.getElementById('modalCard').innerHTML = `<button class="modal-close" onclick="closeModal()">${ic('close',15)}</button>` + html;
  document.getElementById('modalCard').querySelector('.modal-close span').style.color="var(--dark)";
  document.getElementById('modalBg').classList.add('show');
}
function closeModal(){ document.getElementById('modalBg').classList.remove('show'); }
document.getElementById('modalBg').addEventListener('click',e=>{ if(e.target.id==='modalBg') closeModal(); });

function shareRow(title){
  const url = encodeURIComponent(location.href.split('#')[0]);
  const text = encodeURIComponent(title);
  return `<div class="share-row">
    <a href="https://wa.me/?text=${text}%20${url}" target="_blank" rel="noopener" title="Partager sur WhatsApp">${ic('whatsapp',16)}</a>
    <a href="https://www.facebook.com/sharer/sharer.php?u=${url}" target="_blank" rel="noopener" title="Partager sur Facebook">${ic('facebook',16)}</a>
    <a href="https://www.linkedin.com/sharing/share-offsite/?url=${url}" target="_blank" rel="noopener" title="Partager sur LinkedIn">${ic('linkedin',16)}</a>
  </div>`;
}

