function showProduct(id){
  const p = state.produits.find(x=>x.id===id); if(!p) return;
  openModal(`
    <div class="product-cover" style="height:120px;border-radius:14px;background:linear-gradient(135deg,${PROD_COLORS[p.categorie]},var(--dark));margin-bottom:18px;">
      <div class="cicon">${ic('cart',30)}</div>
    </div>
    <span class="actor-cat">${p.categorie}</span>
    <h3 style="font-size:1.15rem;color:var(--dark);margin:8px 0 4px;">${p.nom}</h3>
    <div class="product-price" style="margin-bottom:10px;">${fmtPrice(p.prix)}</div>
    <p style="color:var(--gray);font-size:0.92rem;margin-bottom:14px;">${p.desc}</p>
    <p class="product-meta" style="margin-bottom:18px;">Vendu par <b style="color:var(--dark)">${p.vendeur}</b> · ${p.ville}</p>
    <a href="#contact" onclick="closeModal()" class="btn btn-primary btn-block">${ic('link',16)} Contacter le vendeur</a>
    ${shareRow(p.nom)}
  `);
}
function showArticle(id){
  const a = state.articles.find(x=>x.id===id); if(!a) return;
  const f = new Date(a.date+"T00:00:00");
  openModal(`
    <div class="res-cover" style="height:110px;border-radius:14px;margin-bottom:18px;"></div>
    <span class="actor-cat">${a.categorie}</span>
    <h3 style="font-size:1.15rem;color:var(--dark);margin:8px 0 4px;">${a.titre}</h3>
    <p class="res-meta" style="margin-bottom:14px;">Par ${a.auteur} · ${f.getDate()} ${MONTHS_FULL[f.getMonth()]} ${f.getFullYear()}</p>
    <p style="color:var(--gray);font-size:0.92rem;">${a.extrait}</p>
    ${shareRow(a.titre)}
  `);
}
function loginModal(){
  openModal(`
    <div style="text-align:center;margin-bottom:6px;">
      <div class="picon" style="width:48px;height:48px;border-radius:14px;background:var(--tint);display:flex;align-items:center;justify-content:center;margin:0 auto 14px;color:var(--primary)">${ic('lock',22)}</div>
      <h3 style="color:var(--dark);font-size:1.15rem;">Connexion</h3>
      <p style="color:var(--gray);font-size:0.85rem;margin-top:4px;">Accédez à votre profil Eco Togo Connect.</p>
    </div>
    <form id="loginForm" style="margin-top:20px;">
      <div class="field"><label>Adresse email</label><input type="email" id="liEmail" required placeholder="vous@exemple.com"></div>
      <div class="field"><label>Mot de passe</label><input type="password" id="liPass" required placeholder="••••••••"></div>
      <button class="btn btn-primary btn-block">Se connecter</button>
    </form>
    <p class="switch-line">Pas encore de compte ? <button onclick="signupModal()">S'inscrire</button></p>
  `);
  document.getElementById('loginForm').addEventListener('submit',e=>{ e.preventDefault(); closeModal(); toast("Connexion réussie (démo)."); });
}
function signupModal(){
  openModal(`
    <div style="text-align:center;margin-bottom:6px;">
      <div class="picon" style="width:48px;height:48px;border-radius:14px;background:var(--tint);display:flex;align-items:center;justify-content:center;margin:0 auto 14px;color:var(--primary)">${ic('userplus',22)}</div>
      <h3 style="color:var(--dark);font-size:1.15rem;">Créer un compte</h3>
      <p style="color:var(--gray);font-size:0.85rem;margin-top:4px;">Rejoignez la communauté des acteurs verts du Togo.</p>
    </div>
    <form id="signupForm" style="margin-top:20px;">
      <div class="field"><label>Nom complet</label><input id="suNom" required></div>
      <div class="field"><label>Adresse email</label><input type="email" id="suEmail" required></div>
      <div class="field"><label>Vous êtes</label>
        <select id="suRole"><option>Entreprise verte</option><option>Vendeur / prestataire</option><option>ONG / Association</option><option>Consommateur écoresponsable</option></select>
      </div>
      <div class="field"><label>Mot de passe</label><input type="password" id="suPass" required></div>
      <button class="btn btn-primary btn-block">Créer mon compte</button>
    </form>
    <p class="switch-line">Déjà inscrit ? <button onclick="loginModal()">Se connecter</button></p>
  `);
  document.getElementById('signupForm').addEventListener('submit',e=>{
    e.preventDefault();
    state.utilisateurs.push({id:Math.max(0,...state.utilisateurs.map(u=>u.id))+1,nom:document.getElementById('suNom').value,email:document.getElementById('suEmail').value,role:document.getElementById('suRole').value,date:new Date().toLocaleDateString('fr-FR')});
    closeModal(); toast("Compte créé avec succès, bienvenue !");
  });
}
document.getElementById('loginBtn').addEventListener('click',loginModal);
document.getElementById('signupBtn').addEventListener('click',signupModal);
document.getElementById('searchIconBtn').addEventListener('click',()=>go('annuaire'));
document.getElementById('bellIconBtn').addEventListener('click',()=>toast("Aucune nouvelle notification pour le moment."));

/* ============ NAV / ROUTER ============ */
const ROUTES = [
  {hash:"home",label:"Accueil"},{hash:"actualites",label:"Actualités"},{hash:"marketplace",label:"Marketplace"},
  {hash:"evenements",label:"Événements"},{hash:"annuaire",label:"Annuaire"},{hash:"apropos",label:"À propos"},
];
function renderChrome(){
  document.querySelectorAll('#footSocial [data-icon]').forEach(a=>{ a.innerHTML = ic(a.dataset.icon,16); });
  const current = (location.hash||"#home").replace("#","");
  document.getElementById('mainNav').innerHTML = ROUTES.map(r=>`<a href="#${r.hash}" class="${current===r.hash?'active':''}">${r.label}</a>`).join("");
  const onAdmin = current==='admin';
  document.querySelector('.head-actions').style.opacity = onAdmin ? '0.4' : '1';
}
function go(hash){ location.hash = hash; }
window.addEventListener('hashchange', route);
window.addEventListener('DOMContentLoaded', route);

function route(){
  const h = (location.hash||"#home").replace("#","");
  renderChrome();
  const app = document.getElementById('app');
  const pages = {home:pageHome,actualites:pageActualites,marketplace:pageMarketplace,evenements:pageEvenements,annuaire:pageAnnuaire,apropos:pageApropos,contact:pageContact,admin:pageAdmin};
  app.innerHTML = (pages[h]||pageHome)();
  window.scrollTo({top:0,behavior:'instant'});
  afterRender(h);
}

