/* ============ PAGE: ANNUAIRE ============ */
function pageAnnuaire(){
  const list = state.acteurs.filter(a=>{
    const matchCat = state.annuaireCat==='Tous' || a.categorie===state.annuaireCat;
    const q = state.annuaireSearch.toLowerCase();
    const matchQ = !q || a.nom.toLowerCase().includes(q) || a.ville.toLowerCase().includes(q) || a.desc.toLowerCase().includes(q);
    return matchCat && matchQ && a.statut==='Validé';
  });
  return `
  <div class="pagehead"><div class="wrap">
    <span class="tag-eyebrow">Annuaire</span><h1>Les acteurs de l'économie verte au Togo</h1>
    <p>Découvrez les entreprises, ONG et entrepreneurs qui font avancer la transition écologique — filtrez par catégorie ou recherchez par nom et ville.</p>
  </div></div>
  <section style="padding-top:0"><div class="wrap">
    <div class="filters-bar">
      <div class="searchbox">${ic('search',16)}<input id="searchInput" placeholder="Rechercher un acteur, une ville..." value="${state.annuaireSearch}"></div>
      <div class="chip-row" id="chipRow">${["Tous",...CATS].map(c=>`<button class="chip ${state.annuaireCat===c?'active':''}" data-cat="${c}">${c}</button>`).join("")}</div>
    </div>
    ${list.length? `<div class="card-grid">${list.map(a=>`
      <div class="actor-card">
        <div class="actor-top">
          <div class="avatar-sq" style="background:${catColor(a.categorie)}">${initials(a.nom)}</div>
          <div><span class="actor-cat">${a.categorie}</span><h3>${a.nom}</h3><div class="city">${ic('pin',13)}${a.ville}</div></div>
        </div>
        <p class="desc">${a.desc}</p>
        <div class="actor-foot"><span>${a.contact}</span><button class="btn btn-ghost btn-sm" onclick="showActor(${a.id})">Voir le profil</button></div>
      </div>`).join("")}</div>` : `<div class="empty-state"><div class="picon" style="color:var(--gray)">${ic('search',24)}</div><h3 style="color:var(--dark);margin-bottom:6px;">Aucun résultat</h3><p>Essayez une autre recherche ou changez de catégorie.</p></div>`}
  </div></section>`;
}

/* ============ PAGE: MARKETPLACE ============ */
function pageMarketplace(){
  const list = state.produits.filter(p=>{
    const matchCat = state.marketCat==='Tous' || p.categorie===state.marketCat;
    const q = state.marketSearch.toLowerCase();
    const matchQ = !q || p.nom.toLowerCase().includes(q) || p.vendeur.toLowerCase().includes(q);
    return matchCat && matchQ && p.statut==='Validé';
  });
  return `
  <div class="pagehead"><div class="wrap">
    <span class="tag-eyebrow">Marketplace</span><h1>La place de marché verte du Togo</h1>
    <p>Achetez et vendez des produits et services écologiques directement auprès des acteurs référencés.</p>
  </div></div>
  <section style="padding-top:0"><div class="wrap">
    <div class="filters-bar">
      <div class="searchbox">${ic('search',16)}<input id="marketSearchInput" placeholder="Rechercher un produit, un vendeur..." value="${state.marketSearch}"></div>
      <div class="chip-row" id="marketChipRow">${["Tous",...PROD_CATS].map(c=>`<button class="chip ${state.marketCat===c?'active':''}" data-cat="${c}">${c}</button>`).join("")}</div>
    </div>
    ${list.length? `<div class="card-grid">${list.map(p=>`
      <div class="product-card">
        <div class="product-cover" style="background:linear-gradient(135deg,${PROD_COLORS[p.categorie]},var(--dark))"><div class="cicon">${ic('cart',26)}</div></div>
        <div class="product-body">
          <span class="actor-cat">${p.categorie}</span>
          <h3>${p.nom}</h3>
          <div class="product-price">${fmtPrice(p.prix)}</div>
          <p class="product-meta">${p.vendeur} · ${p.ville}</p>
          <div class="product-foot"><button class="btn btn-primary btn-sm" style="flex:1;justify-content:center;" onclick="showProduct(${p.id})">Voir le produit</button></div>
        </div>
      </div>`).join("")}</div>` : `<div class="empty-state"><div class="picon" style="color:var(--gray)">${ic('cart',24)}</div><h3 style="color:var(--dark);margin-bottom:6px;">Aucun produit trouvé</h3><p>Essayez une autre recherche ou changez de catégorie.</p></div>`}
  </div></section>`;
}

